#include <stdio.h>
#include <stdlib.h>

static int grp[1000000];

static inline int readint(void) {
    int c = getchar_unlocked();
    while (c != '-' && (c < '0' || c > '9')) c = getchar_unlocked();
    int sgn = 1;
    if (c == '-') { sgn = -1; c = getchar_unlocked(); }
    int x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = getchar_unlocked(); }
    return x * sgn;
}

int main(void) {
    int E = readint(), M = readint(), D = readint();

    int *a1 = (int *)malloc(sizeof(int) * (M > 0 ? M : 1));
    int *a2 = (int *)malloc(sizeof(int) * (M > 0 ? M : 1));
    int *b1 = (int *)malloc(sizeof(int) * (D > 0 ? D : 1));
    int *b2 = (int *)malloc(sizeof(int) * (D > 0 ? D : 1));

    for (int i = 0; i < M; i++) {
        a1[i] = readint();
        a2[i] = readint();
    }
    for (int i = 0; i < D; i++) {
        b1[i] = readint();
        b2[i] = readint();
    }

    int G = E / 3;
    for (int g = 0; g < G; g++) {
        int i = readint(), j = readint(), k = readint();
        grp[i] = g;
        grp[j] = g;
        grp[k] = g;
    }

    long long violations = 0;
    for (int i = 0; i < M; i++)
        if (grp[a1[i]] != grp[a2[i]]) violations++;
    for (int i = 0; i < D; i++)
        if (grp[b1[i]] == grp[b2[i]]) violations++;

    printf("%lld\n", violations);

    free(a1); free(a2); free(b1); free(b2);
    return 0;
}
